                    checkBox.BackgroundImageLayout = ImageLayout.Zoom;
                    kolejnosc = obrazek.kolejnosc;
                }
                else
                {
                    checkBox.Name = "brak";
                    checkBox.Text = "";
                    kolejnosc = 0;
